                <!-- بخش سمت چپ (تبدیل شده به Owl Carousel) -->
                <div id="courses-slider" class="courses-track owl-carousel owl-theme">
                    <?php
                    // کوئری برای دریافت دوره‌های لرن‌دش
                    $args = [
                        'post_type'      => 'sfwd-courses', // پست تایپ اختصاصی دوره های لرن‌دش
                        'posts_per_page' => 8,              // تعداد دوره‌های در حال نمایش در اسلایدر
                        'post_status'    => 'publish',
                    ];

                    $courses_query = new WP_Query($args);

                    if ($courses_query->have_posts()) :
                        while ($courses_query->have_posts()) : $courses_query->the_post();
                            $course_id = get_the_ID();

                            // دریافت قیمت دوره از تنظیمات نیتیو لرن‌دش
                            $course_meta = get_post_meta($course_id, '_sfwd-courses', true);
                            $price = isset($course_meta['sfwd-courses_course_price']) ? $course_meta['sfwd-courses_course_price'] : '';
                            $price_type = isset($course_meta['sfwd-courses_course_price_type']) ? $course_meta['sfwd-courses_course_price_type'] : '';
                    ?>
                            <div class="course-card-pro">
                                <div class="card-image-box">
                                    <a href="<?php the_permalink(); ?>">
                                        <?php if (has_post_thumbnail()) : ?>
                                            <?php the_post_thumbnail("medium", ['alt' => get_the_title()]); ?>
                                        <?php else : ?>
                                            <img src="<?php echo PATH_DIR_URL; ?>/assets/img/front-page/Screenshot.webp" alt="<?php the_title_attribute(); ?>">
                                        <?php endif; ?>
                                    </a>
                                </div>
                                <div class="card-body">
                                    <h3 class="card-title">
                                        <a href="<?php the_permalink(); ?>"><?= get_the_title(); ?></a>
                                    </h3>

                                    <p class="card-teacher"><?php the_author(); ?></p>

                                    <div class="card-tags">
                                        <?php
                                        $course_terms = get_the_terms($course_id, 'ld_course_category');
                                        $course_tags  =  get_the_terms($course_id, 'ld_course_tag');
                                        if ($course_terms && ! is_wp_error($course_terms)) :
                                            foreach ($course_terms as $term) : ?>
                                                <span class="tag tag-orange"><?= esc_html($term->name); ?></span>
                                            <?php endforeach;
                                        endif;
                                        if ($course_tags && ! is_wp_error($course_tags)) :
                                            foreach ($course_tags as $tag) : ?>
                                                <span class="tag tag-orange"><?= esc_html($tag->name); ?></span>
                                        <?php endforeach;
                                        endif;
                                        ?>
                                    </div>

                                    <div class="card-price-box">
                                        <?php if ($price_type === 'open' || $price_type === 'free' || empty($price)) : ?>
                                            <div class="price-current">رایگان</div>
                                        <?php else : ?>
                                            <div class="price-current">
                                                <?php
                                                // فرمت‌دهی سه رقم سه رقم قیمت
                                                echo is_numeric($price) ? number_format((float)$price) : esc_html($price);
                                                ?>
                                                <span>تومان</span>
                                            </div>
                                        <?php endif; ?>
                                    </div>
                                </div>
                            </div>
                    <?php
                        endwhile;
                        wp_reset_postdata(); // ریست کردن دیتا لایه پست‌ها
                    endif;
                    ?>
                </div>
            </div>
        </div>
    </section>


